def longest_orf_aa(s):
    best=0
    for strand in (s, s.translate(str.maketrans("ACGT","TGCA"))[::-1]):
        for f in range(3):
            pos=f; cur=None
            while pos+3<=len(strand):
                c=strand[pos:pos+3]
                if cur is None:
                    if c=="ATG": cur=pos
                else:
                    if c in stops:
                        best=max(best,(pos-cur)//3); cur=None
                pos+=3
