import random
seq = open("region.fasta").read().split("\n",1)[1]
seq="".join(seq.split())
n=len(seq)
comp=str.maketrans("ACGT","TGCA")
stops={"TAA","TAG","TGA"}

# Build order-3 Markov transition counts
from collections import defaultdict
trans=defaultdict(lambda: [0,0,0,0])  # ACGT
idx={b:i for i,b in enumerate("ACGT")}
for i in range(n-3):
    ctx=seq[i:i+3]
    nxt=seq[i+3]
    trans[ctx][idx[nxt]]+=1
# convert to cumulative probabilities
cum={}
for ctx,cnts in trans.items():
    tot=sum(cnts)
    c=[]; s=0
    for x in cnts:
        s+=x/tot; c.append(s)
    cum[ctx]=c

def gen(seed):
    random.seed(seed)
    s=list(seq[:3])
    for i in range(3,n):
        ctx="".join(s[-3:])
        c=cum.get(ctx)
        if c is None:
            s.append(random.choice("ACGT")); continue
        r=random.random()
        for j,p in enumerate(c):
            if r<=p:
                s.append("ACGT"[j]); break
        else:
            s.append("ACGT"[3])
    return "".join(s)

def longest(s):
    best=0
    for strand in (s, s.translate(comp)[::-1]):
        L=len(strand)
        for f in range(3):
            cur=-1
            for pos in range(f, L-2, 3):
                c=strand[pos:pos+3]
                if cur<0:
                    if c=="ATG": cur=pos
                elif c in stops:
                    d=(pos-cur)//3
                    if d>best: best=d
                    cur=-1
            if cur>=0:
                d=(L-cur)//3
                if d>best: best=d
    return best

N=500
res=[]
for t in range(N):
    res.append(longest(gen(t)))
res.sort()
print("order-3 Markov null, N=",N)
print("mean",round(sum(res)/len(res),1),"median",res[len(res)//2],"max",max(res))
for thr in (238,338):
    print(f"P(longest>={thr}):", sum(1 for r in res if r>=thr)/N)
"}

